<template>
  <div class="categories">
    <div class="category-toolbar"><div class="category-heading"><strong>商品分类匹配规则</strong><span>商品名称包含关键词时匹配；优先匹配更长的关键词</span></div><div class="category-actions"><span>{{ rows.length }} 条规则</span><button class="primary" :disabled="saving" @click="start()">新增分类</button></div></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p>
    <div class="category-table-wrap" :aria-busy="loading">
      <table><colgroup><col style="width:45%" /><col /><col style="width:220px" /></colgroup><thead><tr><th>匹配关键词</th><th>商品分类</th><th class="actions">操作</th></tr></thead><tbody>
        <tr v-for="row in rows" :key="row.id"><td>{{ row.keyword }}</td><td><span class="rule-category">{{ row.category }}</span></td><td class="actions"><template v-if="deleting === row.id"><span>删除此规则？</span><button class="danger" :disabled="saving" @click="remove(row)">删除</button><button :disabled="saving" @click="deleting=null">取消</button></template><template v-else><button :disabled="saving" @click="start(row)">编辑</button><button class="danger" :disabled="saving" @click="deleting=row.id">删除</button></template></td></tr>
        <tr v-if="!loading && !rows.length"><td colspan="3" class="empty">暂无分类规则，点击“新增分类”添加</td></tr>
      </tbody></table>
      <div v-if="loading" class="loading" role="status">正在加载数据…</div>
    </div>
    <Teleport to="body"><div v-if="editing !== null" class="rule-dialog" @click.self="closeEditor"><form class="rule-form" role="dialog" aria-modal="true" aria-labelledby="category-form-title" @submit.prevent="save" @keydown.esc="closeEditor"><div class="rule-form-head"><strong id="category-form-title">{{ editing === 0 ? '新增商品分类' : '编辑商品分类' }}</strong><button type="button" aria-label="关闭表单" :disabled="saving" @click="closeEditor">×</button></div><label>匹配关键词<input ref="keywordInput" v-model="draft.keyword" required maxlength="200" placeholder="例如 Dutch Oven" :disabled="saving" /></label><label>商品分类<input v-model="draft.category" required maxlength="100" placeholder="例如 荷兰锅" :disabled="saving" /></label><p v-if="formError" class="error" role="alert">{{ formError }}</p><div class="rule-form-actions"><button type="button" :disabled="saving" @click="closeEditor">取消</button><button type="submit" class="primary" :disabled="saving">{{ saving ? '保存中…' : '保存规则' }}</button></div></form></div></Teleport>
  </div>
</template>
<script setup>
import { ref, reactive, nextTick, onMounted } from 'vue'
import request from '@/utils/request'
const rows=ref([]), loading=ref(false), saving=ref(false), error=ref(''), formError=ref(''), editing=ref(null), deleting=ref(null), keywordInput=ref(null)
const draft=reactive({keyword:'',category:''}), endpoint='/tax-data/amazon/product-categories'
async function load(){loading.value=true;error.value='';try{rows.value=(await request.get(endpoint)).data.items||[]}catch(e){error.value=e.response?.data?.error||'分类规则加载失败'}finally{loading.value=false}}
async function start(row){editing.value=row?.id||0;deleting.value=null;formError.value='';draft.keyword=row?.keyword||'';draft.category=row?.category||'';await nextTick();keywordInput.value?.focus()}
function closeEditor(){if(!saving.value)editing.value=null}
async function save(){if(saving.value)return;const body={keyword:draft.keyword.trim(),category:draft.category.trim()};if(!body.keyword||!body.category){formError.value='请填写匹配关键词和商品分类';return}saving.value=true;formError.value='';try{const r=editing.value?await request.put(`${endpoint}/${editing.value}`,body):await request.post(endpoint,body);if(editing.value)rows.value=rows.value.map(row=>row.id===editing.value?r.data:row);else rows.value.push(r.data);editing.value=null}catch(e){formError.value=e.response?.data?.error||'保存失败，请重试'}finally{saving.value=false}}
async function remove(row){saving.value=true;error.value='';try{await request.delete(`${endpoint}/${row.id}`);rows.value=rows.value.filter(item=>item.id!==row.id);deleting.value=null}catch(e){error.value=e.response?.data?.error||'删除失败，请重试'}finally{saving.value=false}}
defineExpose({load})
onMounted(load)
</script>
<style scoped>
.categories{display:flex;flex:1;flex-direction:column;min-height:0;min-width:0}.category-toolbar{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:14px 18px;border-bottom:1px solid #e8edf2}.category-heading,.category-actions{display:flex;align-items:baseline;gap:12px}.category-heading strong{color:#33485b;font-size:13px}.category-heading span,.category-actions>span{color:#8997a4;font-size:11px;line-height:1.5}.category-actions{align-items:center;flex-shrink:0}.rule-category{display:inline-block;padding:3px 8px;border-radius:12px;color:#285d83;background:#eaf3f8;font-size:11px}.category-table-wrap{position:relative;flex:1;min-height:0;overflow:auto}
table{width:100%;min-width:600px;border-collapse:separate;border-spacing:0;table-layout:fixed;font-size:12px}th,td{padding:12px 18px;text-align:left;border-bottom:1px solid #e8edf2;overflow-wrap:anywhere}th{position:sticky;top:0;z-index:2;background:#f4f6f9;color:#596b7e;height:44px;box-sizing:border-box}td{height:54px;box-sizing:border-box;color:#455961}tbody tr:hover{background:#f8fafc}.actions{text-align:right;white-space:nowrap}.actions button+button{margin-left:6px}.actions span{font-size:11px;color:#8492a0;margin-right:8px}
input{width:100%;box-sizing:border-box;height:34px;padding:0 10px;border:1px solid #cbd8e2;border-radius:5px;color:#33485b;font:inherit;background:#fff}button{height:30px;padding:0 11px;border:1px solid #dce4e7;border-radius:5px;background:#fff;color:#465669;font-size:12px;cursor:pointer}button:hover{background:#f3f6f9}button:disabled{opacity:.5;cursor:default}.primary{color:#285d83;border-color:#c3d5e3;background:#f4f8fb}.danger{color:#a34635}.empty{text-align:center;height:132px;color:#89949b}.error{margin:12px 18px;color:#a34635;font-size:12px}.loading{position:absolute;inset:0;display:grid;place-items:center;background:rgb(255 255 255 / 70%);font-size:12px;color:#62788b}button:focus-visible,input:focus-visible{outline:2px solid #285d83;outline-offset:2px}
.rule-dialog{position:fixed;inset:0;z-index:1100;display:grid;place-items:center;padding:20px;background:rgb(20 36 50 / 35%)}.rule-form{box-sizing:border-box;width:min(520px,100%);max-height:calc(100dvh - 40px);overflow:auto;padding:22px;border:1px solid #dce5eb;border-radius:12px;background:#fff;box-shadow:0 20px 50px rgb(20 45 65 / 22%)}.rule-form-head,.rule-form-actions{display:flex;align-items:center;justify-content:space-between}.rule-form-head{margin-bottom:16px;color:#33485b;font-size:16px}.rule-form-head button{border:0;background:transparent;font-size:22px}.rule-form label{display:block;margin-top:11px;color:#5b6d7d;font-size:12px}.rule-form input{display:block;width:100%;box-sizing:border-box;height:auto;margin-top:5px;padding:8px 10px;border:1px solid #d9e3e8;border-radius:6px;color:#33485b;font:inherit}.rule-form-actions{justify-content:flex-end;gap:8px;margin-top:18px}.rule-form .error{margin:12px 0 0}
@media(max-width:700px){.category-toolbar{align-items:flex-start}.category-heading{flex-direction:column;gap:4px}.category-toolbar button{flex-shrink:0}}
</style>
